package com.solune.app;
import androidx.webkit.WebViewCompat;import androidx.webkit.WebViewFeature;import java.util.Collections;import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import android.view.*;import android.Manifest;import android.content.pm.PackageManager;
public class MainActivity extends Activity {
 WebView web;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff161615);getWindow().setNavigationBarColor(0xff161615);web=new WebView(this);web.setBackgroundColor(0xff161615);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);if(!WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER)){setContentView(new android.widget.TextView(this){{setText("Обновите Android System WebView");}});return;} WebViewCompat.addWebMessageListener(web,"SoluneNative",Collections.singleton("https://solune.local"),(v,msg,origin,main,reply)->{if(!main)return;String data=msg.getData();if("drain".equals(data))reply.postMessage(EngineService.drain());else if("cancel".equals(data))EngineService.cancel();else {try{org.json.JSONObject q=new org.json.JSONObject(data);if("saveFile".equals(q.optString("type"))){saveFile(q);return;}}catch(Exception ignored){}new Bridge().submit(data);}});web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().equals("https://solune.local/index.html");} @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(r.getUrl().toString().equals("https://solune.local/index.html")){try{return new WebResourceResponse("text/html","UTF-8",getAssets().open("index.html"));}catch(Exception e){return null;}}String scheme=r.getUrl().getScheme();if("data".equals(scheme)||"blob".equals(scheme)||"about".equals(scheme))return null;if("https".equals(scheme)&&"fggh567-solune.hf.space".equals(r.getUrl().getHost())&&r.getUrl().getPath()!=null&&r.getUrl().getPath().startsWith("/v1/"))return null;return new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));}});web.loadUrl("https://solune.local/index.html");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},1);}
 byte[] pendingFile;
 void saveFile(org.json.JSONObject q){try{if(pendingFile!=null)return;String encoded=q.getString("base64");if(encoded.length()>5500000)throw new IllegalArgumentException();byte[] bytes=android.util.Base64.decode(encoded,android.util.Base64.DEFAULT);if(bytes.length>4000000)throw new IllegalArgumentException();pendingFile=bytes;String name=q.optString("name","solune.txt").replaceAll("[^a-zA-Z0-9_.-]","_");Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(q.optString("mime","application/octet-stream"));intent.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(intent,71);}catch(Exception e){pendingFile=null;android.widget.Toast.makeText(this,"Не удалось подготовить файл",0).show();}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=71)return;byte[] bytes=pendingFile;pendingFile=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&bytes!=null){try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new java.io.IOException();out.write(bytes);android.widget.Toast.makeText(this,"Файл сохранён",0).show();}catch(Exception e){android.widget.Toast.makeText(this,"Не удалось сохранить файл",0).show();}}}
 class Bridge { @JavascriptInterface public void submit(String json){runOnUiThread(()->{Intent i=new Intent(MainActivity.this,EngineService.class);i.putExtra("request",json);startForegroundService(i);});} @JavascriptInterface public String drain(){return EngineService.drain();} @JavascriptInterface public void cancel(){EngineService.cancel();} }
 @Override public void onBackPressed(){web.evaluateJavascript("document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape'}))",null);}
}
